 public void stopPlayback(){generation++;if(system!=null){system.stopPlayback();removeView(system);system=null;systemMedia=null;nativeSubtitle=-1;}if(relay!=null){relay.close();relay=null;}final org.videolan.libvlc.MediaPlayer old=player;final LibVLC lib=engine;player=null;engine=null;if(old!=null){old.setEventListener(null);try{old.setVideoTrackEnabled(false);old.getVLCVout().detachViews();}catch(Exception ignored){}cleanup.submit(new Runnable(){public void run(){try{old.stop();}catch(Exception ignored){}finally{try{old.release();}catch(Exception ignored){}if(lib!=null)try{lib.release();}catch(Exception ignored){}}}});}else if(lib!=null)lib.release();if(videoFrame!=null){removeView(videoFrame);videoFrame=null;}surface=null;subtitleSurface=null;width=height=visibleWidth=visibleHeight=0;}
 private String trustDirectory()throws Exception{File dir=getContext().getDir("engine-ca",0);File marker=new File(dir,"ready-v1");if(!marker.exists()){InputStream in=getContext().getAssets().open("cacert.pem");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;try{while((n=in.read(b))!=-1)out.write(b,0,n);}finally{in.close();}java.util.regex.Matcher m=java.util.regex.Pattern.compile("-----BEGIN CERTIFICATE-----[\\s\\S]*?-----END CERTIFICATE-----").matcher(new String(out.toByteArray(),"UTF-8"));int i=0;while(m.find()){FileOutputStream file=new FileOutputStream(new File(dir,"ca-"+(i++)+".pem"));try{file.write(m.group().getBytes("US-ASCII"));}finally{file.close();}}if(i==0)throw new IOException("Empty CA bundle");marker.createNewFile();}return dir.getAbsolutePath();}
